// ---------------------------------------------------------------------------
// NO Shopify token. Matches products by a shared TAG (e.g. 'relay-1001') that
// you put on the SAME product in BOTH stores. Uses each store's PUBLIC feed
// (https://STORE/products.json) which includes tags.
//   Store A order gives product_id -> look up Store A's relay tag
//   -> find the Store B product with the same tag -> build the checkout link.
// ---------------------------------------------------------------------------
const TAG_PREFIX = 'relay-';                    // both products share e.g. relay-1001
const STORE_B = 'montre-usa.myshopify.com';     // supplier store (checkout happens here)
const STORE_A_FALLBACK = '';                    // optional; auto-detected from the webhook

const input = $input.first().json;
const order = input.body || input;
const headers = input.headers || {};
const STORE_A = String(headers['x-shopify-shop-domain'] || STORE_A_FALLBACK || '').trim();

const items = order.line_items || [];
const cust = order.customer || {};
const ship = order.shipping_address || {};
const email = order.email || cust.email || '';

const relayTagOf = (tags) => {
  const arr = Array.isArray(tags) ? tags : String(tags || '').split(',');
  let numeric = null;
  for (const t of arr) {
    const s = String(t).trim().toLowerCase();
    if (s.startsWith(TAG_PREFIX)) return s;      // e.g. relay-1001
    if (!numeric && /^\d+$/.test(s)) numeric = s; // e.g. plain number 1
  }
  return numeric;
};

const loadFeed = async (domain) => {
  const out = [];
  if (!domain) return out;
  for (let page = 1; page <= 10; page++) {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://${domain}/products.json?limit=250&page=${page}`,
      json: true,
    });
    const products = (res && res.products) || [];
    if (!products.length) break;
    out.push(...products);
  }
  return out;
};

// Store A: product_id -> relay tag
const aTagById = new Map();
for (const p of await loadFeed(STORE_A)) {
  const tag = relayTagOf(p.tags);
  if (tag) aTagById.set(String(p.id), tag);
}

// Store B: relay tag -> variant id
const bVariantByTag = new Map();
for (const p of await loadFeed(STORE_B)) {
  const tag = relayTagOf(p.tags);
  const firstV = p.variants && p.variants[0];
  if (tag && firstV) bVariantByTag.set(tag, firstV.id);
}

const parts = [];
const unmatched = [];
for (const li of items) {
  const tag = aTagById.get(String(li.product_id));
  const vid = tag ? bVariantByTag.get(tag) : null;
  if (vid) parts.push(`${vid}:${li.quantity || 1}`);
  else unmatched.push(li.title + (tag ? ` [${tag} missing on Store B]` : ' [no relay tag on Store A]'));
}

const enc = encodeURIComponent;
let link = '';
if (parts.length) {
  const q = [
    email ? `checkout[email]=${enc(email)}` : '',
    `checkout[shipping_address][first_name]=${enc(ship.first_name || cust.first_name || '')}`,
    `checkout[shipping_address][last_name]=${enc(ship.last_name || cust.last_name || '')}`,
    `checkout[shipping_address][address1]=${enc(ship.address1 || '')}`,
    `checkout[shipping_address][city]=${enc(ship.city || '')}`,
    `checkout[shipping_address][province]=${enc(ship.province || '')}`,
    `checkout[shipping_address][country]=${enc(ship.country || 'Egypt')}`,
    `checkout[shipping_address][phone]=${enc(ship.phone || cust.phone || '')}`,
  ].filter(Boolean).join('&');
  link = `https://${STORE_B}/cart/${parts.join(',')}?${q}`;
}

return [{
  json: {
    orderName: order.name || null,
    storeA: STORE_A,
    ready: Boolean(link) && Boolean(email),
    email,
    firstName: ship.first_name || cust.first_name || 'there',
    link,
    unmatched,
  },
}];
